Uses `cn` from `@/lib/utils` and Tailwind classes matching shadcn-style conventions. Here's a class-based `ErrorBoundary` matching that style:

```tsx
"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

interface ErrorBoundaryProps {
  children: React.ReactNode
  fallback?: React.ReactNode | ((error: Error, reset: () => void) => React.ReactNode)
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void
  className?: string
}

interface ErrorBoundaryState {
  error: Error | null
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props)
    this.state = { error: null }
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { error }
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    this.props.onError?.(error, errorInfo)
  }

  reset = () => {
    this.setState({ error: null })
  }

  render() {
    const { error } = this.state
    const { children, fallback, className } = this.props

    if (error) {
      if (typeof fallback === "function") {
        return fallback(error, this.reset)
      }

      if (fallback) {
        return fallback
      }

      return (
        <div
          data-slot="error-boundary-fallback"
          className={cn(
            "flex flex-col items-center justify-center gap-3 rounded-lg border border-border bg-card p-6 text-center",
            className
          )}
        >
          <p className="text-sm font-medium text-foreground">
            Something went wrong
          </p>
          <p className="text-xs text-muted-foreground">{error.message}</p>
          <button
            type="button"
            onClick={this.reset}
            className="rounded-md border border-border px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-accent hover:text-accent-foreground"
          >
            Try again
          </button>
        </div>
      )
    }

    return children
  }
}

export { ErrorBoundary }
export type { ErrorBoundaryProps }
```

Usage:

```tsx
<ErrorBoundary onError={(err) => console.error(err)}>
  <SomeWidget />
</ErrorBoundary>
```

Note: must be a class component — React error boundaries (`getDerivedStateFromError`/`componentDidCatch`) have no hook equivalent. I didn't write this to a file per your instruction; let me know if you'd like it saved to `my-app/components/ui/ErrorBoundary.tsx`.

